parameters.jsCode:
const aiOutput = items[0].json;
const original = $('Build Local LLM Prompt').item.json;

let parsed;
try {
  let raw = (aiOutput.message && aiOutput.message.content ? aiOutput.message.content : '').trim();
  raw = raw.replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = null;
}

const base = {
  employee_id: original.employee_id,
  full_name: original.full_name,
  email: original.email,
  department: original.department,
  manager: original.manager,
  rule_based_score: original.rule_based_score,
  rule_based_factors: original.rule_based_factors
};

if (!parsed || typeof parsed.risk_score !== 'number') {
  return [{ json: { ...base, llm_parse_status: 'failed', llm_risk_score: null, llm_risk_level: null, llm_key_factors: [], llm_recommended_action: '' } }];
}

return [{ json: {
  ...base,
  llm_parse_status: 'success',
  llm_risk_score: Math.max(0, Math.min(100, Math.round(parsed.risk_score))),
  llm_risk_level: parsed.risk_level || 'Medium',
  llm_key_factors: parsed.key_factors || [],
  llm_recommended_action: parsed.recommended_action || ''
} }];

const d = items[0].json;
const composite = Math.round((d.rule_based_score * 0.4) + (d.llm_risk_score * 0.6));
let level = 'Low';
if (composite >= 70) level = 'High';
else if (composite >= 40) level = 'Medium';

return [{ json: {
  employee_id: d.employee_id,
  full_name: d.full_name,
  email: d.email,
  department: d.department,
  manager: d.manager,
  rule_based_score: d.rule_based_score,
  rule_based_factors: (d.rule_based_factors || []).join('; '),
  llm_risk_score: d.llm_risk_score,
  llm_key_factors: (d.llm_key_factors || []).join('; '),
  llm_recommended_action: d.llm_recommended_action,
  composite_risk_score: composite,
  risk_level: level,
  llm_parse_status: d.llm_parse_status,
  run_date: new Date().toISOString().slice(0,10)
} }];

