You are an HR analytics assistant running strictly on a local, private model. You will be given anonymized employee signal data (no name/email is ever sent to you). Analyze it for flight-risk / attrition signals and respond with ONLY valid JSON, no markdown fences, no commentary, in this exact shape:
{"risk_score": <0-100 integer>, "risk_level": "Low" | "Medium" | "High", "key_factors": ["..."], "recommended_action": "..."}

Weigh engagement trend, attendance pattern, eNPS response, 1:1 note sentiment, and performance trajectory together rather than any single factor in isolation.

parameters.jsCode:
const rows = items.map(i => i.json);
const today = new Date().toISOString().slice(0,10);
const todays = rows.filter(r => r.run_date === today);

const total = todays.length;
const highRisk = todays.filter(r => r.risk_level === 'High');
const mediumRisk = todays.filter(r => r.risk_level === 'Medium');

const byDept = {};
highRisk.forEach(r => { byDept[r.department] = (byDept[r.department] || 0) + 1; });

const factorCounts = {};
todays.forEach(r => {
  (String(r.rule_based_factors || '').split(';')).concat(String(r.llm_key_factors || '').split(';'))
    .map(f => f.trim()).filter(Boolean)
    .forEach(f => { factorCounts[f] = (factorCounts[f] || 0) + 1; });
});
const topFactors = Object.entries(factorCounts).sort((a,b) => b[1]-a[1]).slice(0,5).map(([f,c]) => `${f} (${c})`);

const deptSummary = Object.entries(byDept).map(([d,c]) => `${d}: ${c}`).join(', ') || 'None';

const highRiskList = highRisk.map(r => `- ${r.full_name} (${r.department}, score ${r.composite_risk_score}) — manager: ${r.manager}`).join('\n') || 'No high-risk employees this run.';

const html = `
  <h2>Weekly Employee Retention Risk Digest</h2>
  <p><b>Run date:</b> ${today}</p>
  <p><b>Employees analyzed:</b> ${total}</p>
  <p><b>High risk:</b> ${highRisk.length} &nbsp; <b>Medium risk:</b> ${mediumRisk.length}</p>
  <p><b>High risk by department:</b> ${deptSummary}</p>
  <p><b>Top recurring risk factors this run:</b><br/>${topFactors.join('<br/>')}</p>
  <p><b>Employees flagged for manager follow-up:</b></p>
  <pre>${highRiskList}</pre>
  <p style="color:#888;font-size:12px;">Generated by RetainOS AI. All flight-risk scoring for this run was computed by a locally-hosted LLM — no HR data left your network.</p>
`;

return [{ json: {
  run_date: today,
  total_analyzed: total,
  high_risk_count: highRisk.length,
  medium_risk_count: mediumRisk.length,
  department_breakdown: deptSummary,
  top_factors: topFactors.join(', '),
  digest_html: html
} }];

