  llm_key_factors: '',
  llm_recommended_action: 'Local LLM unavailable this run - rule-based score only. Review manually.',
  composite_risk_score: composite,
  risk_level: level,
  llm_parse_status: 'failed',
  run_date: new Date().toISOString().slice(0,10)
} }];

const d = items[0].json;
const payload = d.llm_payload;

const prompt = `You are an HR analytics assistant running strictly on a local, private model. Analyze this anonymized employee signal data and output ONLY valid JSON (no markdown, no commentary) with this exact shape:
{"risk_score": <0-100 integer>, "risk_level": "Low|Medium|High", "key_factors": ["..."], "recommended_action": "..."}

Employee signal data:
${JSON.stringify(payload, null, 2)}

Consider engagement trend, attendance pattern, eNPS, 1:1 note sentiment, and performance trajectory together rather than any single factor. Return JSON only, no other text.`;

return [{ json: { ...d, llm_prompt: prompt } }];

// Rule-based flight-risk scoring (0-100) + build an ANONYMIZED payload
// (no name/email) that is all the local LLM step will ever see.
return items.map(item => {
  const d = item.json;
  let score = 0;
  const factors = [];

  const decline = d.engagement_score_previous_qtr - d.engagement_score_current;
  if (decline >= 25) { score += 30; factors.push('Sharp engagement score decline'); }
  else if (decline >= 10) { score += 15; factors.push('Moderate engagement score decline'); }

  if (d.attendance_rate_pct < 0.85) { score += 20; factors.push('Attendance below 85%'); }
  else if (d.attendance_rate_pct < 0.92) { score += 10; factors.push('Attendance trending down'); }
  if (d.attendance_trend === 'Declining') { score += 10; factors.push('Declining attendance trend'); }

  if (d.enps_response === 'Detractor') { score += 15; factors.push('eNPS Detractor'); }
  if (d.rating_trend === 'Declining') { score += 15; factors.push('Performance rating declining'); }
  if (d.note_sentiment === 'Negative') { score += 10; factors.push('Negative sentiment in latest 1:1'); }

  score = Math.min(100, score);

  return {
    json: {
      ...d,
      rule_based_score: score,
      rule_based_factors: factors,
      llm_payload: {
        anon_id: d.employee_id,
        tenure_months: d.tenure_months,
        engagement_score_current: d.engagement_score_current,
        engagement_score_previous_qtr: d.engagement_score_previous_qtr,
        manager_relationship_score: d.manager_relationship_score,
        career_growth_score: d.career_growth_score,
        workload_score: d.workload_score,
        enps_response: d.enps_response,
        attendance_rate_pct: d.attendance_rate_pct,
        unplanned_absences: d.unplanned_absences,
        attendance_trend: d.attendance_trend,
        note_summary: d.note_summary,
        rating_trend: d.rating_trend,
        goals_met_pct: d.goals_met_pct,
        peer_feedback_score: d.peer_feedback_score
      }
    }
  };
});

// Combine all 5 HR data sources into a single record per employee.
// Using $('NodeName').all() so this works regardless of which branch
// physically feeds this node's input first.
const master = $('Get Employee Master Data').all().map(i => i.json);
const survey = $('Get Engagement Survey Data').all().map(i => i.json);
const attendance = $('Get Attendance Data').all().map(i => i.json);
const notes = $('Get 1:1 Meeting Notes').all().map(i => i.json);
const reviews = $('Get Performance Review Data').all().map(i => i.json);

function findBy(arr, id) {
  return arr.find(r => r.employee_id === id) || {};
}

const merged = master.map(emp => {
  const id = emp.employee_id;
  const s = findBy(survey, id);
  const a = findBy(attendance, id);
  const n = findBy(notes, id);
  const r = findBy(reviews, id);
  return {
    employee_id: id,
    full_name: emp.full_name,
    email: emp.email,
    department: emp.department,
    manager: emp.manager,
    title: emp.title,
    tenure_months: Number(emp.tenure_months || 0),
    engagement_score_current: Number(s.engagement_score_current || 0),
    engagement_score_previous_qtr: Number(s.engagement_score_previous_qtr || 0),
    score_delta: Number(s.score_delta || 0),
    manager_relationship_score: Number(s.manager_relationship_score || 0),
    career_growth_score: Number(s.career_growth_score || 0),
    workload_score: Number(s.workload_score || 0),
    enps_response: s.enps_response || '',
    attendance_rate_pct: Number(a.attendance_rate_pct || 1),
    unplanned_absences: Number(a.unplanned_absences || 0),
    late_arrivals: Number(a.late_arrivals || 0),
    avg_daily_login_hours: Number(a.avg_daily_login_hours || 8),
    attendance_trend: a.trend_vs_prior_period || 'Stable',
    note_summary: n.note_summary || '',
    note_sentiment: n.sentiment_tag || 'Neutral',
    rating_current: r.rating_current || '',
    rating_previous: r.rating_previous || '',
    rating_trend: r.rating_trend || 'Stable',
    goals_met_pct: Number(r.goals_met_pct || 0),
    peer_feedback_score: Number(r.peer_feedback_score || 0)
  };
});

return merged.map(m => ({ json: m }));
